<?php $title='News';$heading='News Manager';$subheading='Publish homepage updates and announcements.';ob_start(); ?><div class="toolbar"><span></span><a href="/admin/news/new" class="btn btn-gold">+ New Post</a></div><div class="panel"><div class="table-scroll"><table><thead><tr><th>ID</th><th>Title</th><th>Status</th><th>Published</th><th>Author</th><th>Actions</th></tr></thead><tbody><?php foreach($posts as $p): ?><tr><td><?= e($p['id']) ?></td><td><strong><?= e($p['Title']) ?></strong><br><small>/news/<?= e($p['Slug']) ?></small></td><td><?= (int)$p['Published']===1?'<span class="badge good">Published</span>':'<span class="badge">Draft</span>' ?> <?= (int)$p['Pinned']===1?'<span class="badge gold">Pinned</span>':'' ?></td><td><?= e($p['PublishedAt']) ?></td><td><?= e($p['AuthorName']??'') ?></td><td class="row-actions"><a href="/admin/news/<?= e($p['id']) ?>/edit">Edit</a><form method="post" action="/admin/news/<?= e($p['id']) ?>/delete" onsubmit="return confirm('Delete this post?');"><?= csrf_field() ?><button>Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php $content=ob_get_clean();require __DIR__.'/../../layouts/admin.php'; ?>
